define({"topics":[{"title":"Electrical Safety","shortdesc":"<p class=\"shortdesc\">You must follow all recommended safety procedures when servicing and working near energy sources.<\/p>","href":"r_ElectricalSafety_68.html","attributes":{"data-id":"id_2001693"},"menu":{"hasChildren":false},"tocID":"id_2001693-d46e226188","topics":[]},{"title":"Preparing the workstation for a computer replacement","shortdesc":"<p class=\"shortdesc\">Prepare the workstation so all data is saved prior to shutting down and replacing the host computer in the Global Operator Cabinet (GOC).<\/p>","href":"t_PreparingTheWorkstationForAComputerReplacement_6.html","attributes":{"data-id":"id_2007196"},"menu":{"hasChildren":false},"tocID":"id_2007196-d46e226292","topics":[]},{"title":"Shutting down the host computer","shortdesc":"<p class=\"shortdesc\">Shutting down the host computer shuts down the system safely and turns off the power to the host computer.<\/p>","href":"t_ShuttingDownHostComputer_73.html","attributes":{"data-id":"id_2001469"},"menu":{"hasChildren":false},"tocID":"id_2001469-d46e226396","topics":[]},{"title":"Applying LOTO - Global Operator Cabinet (GOC) and operator workspace","shortdesc":"<p class=\"shortdesc\">Apply LOTO before servicing the GOC or items in the operator workspace. Applying LOTO makes sure the environment is safe when working on these items.<\/p>","href":"t_Applying-LOTO-GOCandOWLOTO-Premier_13.html","attributes":{"data-id":"id_2001924"},"menu":{"hasChildren":false},"tocID":"id_2001924-d46e226500","topics":[]},{"title":"Removing the GOC hard drive - Dell T5820","shortdesc":"<p class=\"shortdesc\">Remove the solid state drive (SSD) from the host computer.<\/p>","href":"t_RemovingTheGOCHardDrive-DellT5820.html","attributes":{"data-id":"id_2014917"},"menu":{"hasChildren":false},"tocID":"id_2014917-d46e226604","topics":[]},{"title":"Installing the GOC hard drive - Dell T5820","shortdesc":"<p class=\"shortdesc\">Install the solid state drive (SSD) in the host computer.<\/p>","href":"t_InstallingTheGOCHardDrive-DellT5820.html","attributes":{"data-id":"id_2014918"},"menu":{"hasChildren":false},"tocID":"id_2014918-d46e226708","topics":[]},{"title":"Removing LOTO - Global Operator Cabinet (GOC) and operator workspace","shortdesc":"<p class=\"shortdesc\">Remove LOTO from the GOC and operator workspace before restoring power to these items.<\/p>","href":"t_Removing-LOTO-GOCandOW-Premier_13.html","attributes":{"data-id":"id_2001925"},"menu":{"hasChildren":false},"tocID":"id_2001925-d46e226812","topics":[]},{"title":"Starting up the host computer","shortdesc":"<p class=\"shortdesc\">How to start the host computer.<\/p>","href":"t_StartingUpTheHostComputer_72.html","attributes":{"data-id":"id_2001468"},"menu":{"hasChildren":false},"tocID":"id_2001468-d46e226916","topics":[]},{"title":"Finalizing computer or drive replacement","shortdesc":"<p class=\"shortdesc\">Follow this procedure to finalize a computer or hard drive replacement.<\/p>","href":"t_FinalizingComputerOrDriveReplacement_3.html","attributes":{"data-id":"id_2001779"},"menu":{"hasChildren":false},"tocID":"id_2001779-d46e227020","topics":[]}]});